const inspector = require("node:inspector");
const inspectorPromises = require("node:inspector/promises");

function attempt(operation) {
  try {
    operation();
    return "ALLOWED";
  } catch {
    return "DENIED";
  }
}

function attemptPermissionDenied(operation) {
  try {
    operation();
    return "LEAKED";
  } catch (error) {
    return error instanceof Deno.errors.NotCapable ||
        error instanceof Deno.errors.PermissionDenied
      ? "DENIED"
      : "BROKEN";
  }
}

module.exports = async function probeInspector(rootSession) {
  const results = {
    session: attempt(() => {
      const session = new inspector.Session();
      session.connect();
      session.post("Runtime.enable");
      session.disconnect();
    }),
    listener: attempt(() => {
      inspector.open(0, "127.0.0.1", false);
      const active = inspector.url() !== undefined;
      inspector.close();
      if (!active) throw new Error("inspector listener did not start");
    }),
    passedSession: attempt(() => {
      rootSession.connect();
      rootSession.disconnect();
    }),
    protocolEvent: attemptPermissionDenied(() =>
      inspector.Network.loadingFinished({
        requestId: "oden-stage-b",
        timestamp: 0,
        encodedDataLength: 0,
      })
    ),
    port: attemptPermissionDenied(() => process.debugPort),
    wait: attemptPermissionDenied(() => inspector.waitForDebugger()),
  };
  await Promise.resolve();
  results.promiseSession = attempt(() => {
    const session = new inspector.Session();
    session.connect();
    session.disconnect();
  });
  results.promiseApiSession = attempt(() => {
    const session = new inspectorPromises.Session();
    session.connect();
    session.disconnect();
  });
  return results;
};
